%#codegen
function [q_out, r_out] = split_quotient_remainder_fixpt(u_in, k_in)
% SPLIT_QUOTIENT_REMAINDER Splits unsigned residual u into quotient (q)
% and remainder (r) for Golomb-Rice parameter k (0 <= k <= 8).
%
% Synthesizes to pure barrel-shifter + bit-masking logic (0 DSPs).

fm = get_fimath();

u_val = fi(double(u_in), 0, 10, 0, fm);
k_val = fi(double(k_in), 0, 4, 0, fm);

% Power-of-two lookup avoids exponentiation/divider hardware in HLS
switch k_val
    case fi(0, 0, 1, 0, fm)
        %F2F: No information found for converting the following block of code
        %F2F: Start block
        pow2_k = fi(1, 0, 9, 0, fm);
        %F2F: End block
    case fi(1, 0, 1, 0, fm)
        %F2F: No information found for converting the following block of code
        %F2F: Start block
        pow2_k = fi(2, 0, 9, 0, fm);
        %F2F: End block
    case fi(2, 0, 2, 0, fm)
        pow2_k = fi(4, 0, 9, 0, fm);
    case fi(3, 0, 2, 0, fm)
        pow2_k = fi(8, 0, 9, 0, fm);
    case fi(4, 0, 3, 0, fm)
        pow2_k = fi(16, 0, 9, 0, fm);
    case fi(5, 0, 3, 0, fm)
        pow2_k = fi(32, 0, 9, 0, fm);
    case fi(6, 0, 3, 0, fm)
        pow2_k = fi(64, 0, 9, 0, fm);
    case fi(7, 0, 3, 0, fm)
        pow2_k = fi(128, 0, 9, 0, fm);
    otherwise
        pow2_k = fi(256, 0, 9, 0, fm); % k = 8 max
end

% Quotient: floor(u / 2^k) -> synthesizes to variable right-shift (u >> k)
q_out = fi(floor(fi_div(u_val, pow2_k)), 0, 7, 0, fm);

% Remainder: u - (q * 2^k) -> synthesizes to bit-mask (u & (2^k - 1))
r_out = fi(u_val - (q_out * pow2_k), 0, 8, 0, fm);
end



function ntype = divideType(a,b)
    coder.inline( 'always' );
    nt1 = numerictype( a );
    nt2 = numerictype( b );
    maxFL = max( [ min( nt1.WordLength, nt1.FractionLength ), min( nt2.WordLength, nt2.FractionLength ) ] );
    FL = max( maxFL, 24 );
    extraBits = (FL - maxFL);
    WL = nt1.WordLength + nt2.WordLength;
    WL = min( WL, 124 );
    if (WL + extraBits)<64
        ntype = numerictype( nt1.Signed || nt2.Signed, WL + extraBits, FL );
    else
        ntype = numerictype( nt1.Signed || nt2.Signed, WL, FL );
    end
end


function c = fi_div(a,b)
    coder.inline( 'always' );
    a1 = fi( a, 'RoundMode', 'fix' );
    b1 = fi( b, 'RoundMode', 'fix' );
    nType = divideType( a1, b1 );
    if isfi( a ) && isfi( b ) && isscalar( b )
        c1 = divide( nType, a1, b1 );
        c = fi( c1, numerictype( c1 ), fimath( a ) );
    else
        c = fi( a / b, nType );
    end
end

function fm = get_fimath()
	fm = fimath('RoundingMethod', 'Floor',...
	     'OverflowAction', 'Wrap',...
	     'ProductMode','FullPrecision',...
	     'SumMode','FullPrecision');
end
